    # [doc = " ASCII test optimized to use the `pmovmskb` instruction available on `x86-64`"] # [doc = " platforms."] # [doc = ""] # [doc = " Other platforms are not likely to benefit from this code structure, so they"] # [doc = " use SWAR techniques to test for ASCII in `usize`-sized chunks."] # [cfg (all (target_arch = "x86_64" , target_feature = "sse2"))] # [inline] const fn is_ascii (bytes : & [u8]) -> bool { const CHUNK_SIZE : usize = 32 ; let mut i = 0 ; while i + CHUNK_SIZE <= bytes . len () { let chunk_end = i + CHUNK_SIZE ; let mut count = 0 ; while i < chunk_end { count += bytes [i] . is_ascii () as u8 ; i += 1 ; } if count != CHUNK_SIZE as u8 { return false ; } } let mut is_ascii = true ; while i < bytes . len () { is_ascii &= bytes [i] . is_ascii () ; i += 1 ; } is_ascii }
